// @ts-nocheck – scaffold generated by scripts/build-manifest.mjs; props mirror the manifest's Figma properties.
// Fill FIGMA_NODE_URL once the kit exists, then run `pnpm figma:connect` to publish.
import figma from '@figma/code-connect';
import { ToolUseBlock } from '@davinci-ai/react';

const FIGMA_NODE_URL = 'FIGMA_NODE_URL'; // e.g. https://www.figma.com/design/<file>?node-id=<id>  (Chat/ToolUseBlock)

figma.connect(ToolUseBlock, FIGMA_NODE_URL, {
  props: {
    status: figma.enum('status', { 'running': 'running', 'success': 'success', 'error': 'error' }),
    summary: figma.string('summary'),
    label: figma.string('label'),
  },
  example: ({ label, status, summary }) => (
    <ToolUseBlock status={status} summary={summary}>{label}</ToolUseBlock>
  ),
});
